// One place for the knobs. Slack channel is the workspace channel the
// bot posts to. Change here, nowhere else.
return [{ json: {
  slackChannel: '%%VAO::VAR::SLACK_CHANNEL%%',
  leaseId: $('When Called').first().json.leaseId || '',
  leaseName: $('When Called').first().json.leaseName || ''
} }];

// Build the lookup URLs / formulas from the lease so the HTTP nodes carry no quoting logic.
const AT = 'https://api.airtable.com/v0/%%VAO::BASE_ID%%/';
const L = $('Get Lease').first().json;
const f = L.fields || {};
const first = (v) => Array.isArray(v) ? (v[0] || '') : (v || '');
const unitId = first(f['Unit']);
const propId = first(f['Property (from Unit)']);
const agId = first(f['Applicant Groups']);
const poc = String(first(f['POC Full Name']) || '').trim();
const esc = (s) => String(s).split(String.fromCharCode(92)).join(String.fromCharCode(92, 92)).split(String.fromCharCode(39)).join(String.fromCharCode(92, 39));
const agFormula = poc
  ? 'AND(FIND(' + String.fromCharCode(39) + esc(poc) + String.fromCharCode(39) + ', ARRAYJOIN({Tenants}))>0, {Google Drive Folder}!=' + String.fromCharCode(39, 39) + ')'
  : 'FALSE()';
return [{ json: {
  leaseId: L.id,
  unitUrl: AT + '%%VAO::TBL::Units%%/' + (unitId || 'none'),
  propertyUrl: AT + '%%VAO::TBL::Properties%%/' + (propId || 'none'),
  agUrl: AT + '%%VAO::TBL::Applicant Groups%%/' + (agId || 'none'),
  agFormula: agFormula,
  hasUnit: !!unitId, hasProperty: !!propId, hasAgLink: !!agId
} }];

// State-scoped lookups need the property's state first.
const P = $('Get Property').first().json;
const state = String(((P.fields || {})['State (Select)'] || '')).trim();
const q = String.fromCharCode(39);
return [{ json: {
  state: state,
  stateFormula: state ? '{State}=' + q + state + q : 'FALSE()'
} }];

// ---------------------------------------------------------------------------
// Compute & Validate: deadline, interest, amounts, decision, letter fields.
// Every refuse-to-guess branch from the Relay flows lives here as ok:false + error.
// ---------------------------------------------------------------------------
const NL = String.fromCharCode(10);
const rec = (n) => { try { return $(n).first().json || {}; } catch (e) { return {}; } };
const L = rec('Get Lease'); const lf = L.fields || {};
const U = rec('Get Unit'); const uf = U.fields || {};
const P = rec('Get Property'); const pf = P.fields || {};
const policy = ((rec('Get Policy').records) || [])[0] || null;
const rates = (rec('Get Rates').records) || [];
const settings = ((rec('Get Settings').records) || [])[0] || {}; const sf = settings.fields || {};
const agLinked = rec('Get AG by Link'); const agByTenant = ((rec('Find AG by Tenant').records) || [])[0] || null;

const first = (v) => Array.isArray(v) ? (v[0] === undefined ? '' : v[0]) : (v === undefined || v === null ? '' : v);
const num = (v) => { const n = typeof v === 'number' ? v : parseFloat(v || 0); return isFinite(n) ? n : 0; };
const money = (v) => '$' + num(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const iso = (v) => String(v || '').slice(0, 10);
const dlong = (s) => s ? new Date(s + 'T00:00:00Z').toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' }) : '';
const addDays = (s, n) => new Date(Date.parse(s + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
const todayIso = new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });

const leaseName = String(lf['Lease Name'] || lf['Lease Name (auto)'] || L.id || 'unnamed lease').split(NL)[0].trim();
const problems = [];

// --- inputs the letter cannot do without
const moveOut = iso(lf['Move Out Date - start']);
const leaseStart = iso(lf['Lease Start Date']);
if (!moveOut) problems.push('no Move Out Date - start on the lease');
if (!leaseStart) problems.push('no Lease Start Date on the lease');
const state = String(pf['State (Select)'] || '').trim();
if (!P.id) problems.push('lease has no Unit -> Property link, so the state and address are unknown');
else if (!state) problems.push('property has no State (Select)');
if (!policy) problems.push('no Policy Settings - States row for state ' + (state || '(blank)'));
const templateId = String(sf['Disposition Template Google Doc ID'] || '').trim();
if (!templateId) problems.push('Disposition Template Google Doc ID is blank in Automation Settings');

// --- deposit folder: AG linked on the lease, else the AG that lists this tenant
const folderUrl = String(((agLinked.fields || {})['Google Drive Folder']) || ((agByTenant && agByTenant.fields) || {})['Google Drive Folder'] || '').trim();
const fm = folderUrl.match(/folders\/([A-Za-z0-9_-]+)/);
const folderId = fm ? fm[1] : '';
if (!folderId) problems.push('no leasing folder: the lease has no Applicant Group with a Google Drive Folder, and no Applicant Group lists ' + (String(first(lf['POC Full Name'])) || 'the point of contact'));

// --- money
const deposit = num(lf['Total Security Deposit']);
const petDep = num(lf['Pet Deposit']);
const held = deposit + petDep;
if (held <= 0) problems.push('Total Deposits Held is $0 - nothing to dispose');
const ded = {
  repair: num(lf['Deduction - R&M']), cleaning: num(lf['Deduction - Cleaning']), missing: num(lf['Deduction - Missing Items']),
  damaged: num(lf['Deduction - Damaged Items']), pet: num(lf['Deduction - Pet Damage']), rent: num(lf['Deduction - Unpaid Rent'])
};
const deductions = Math.round((ded.repair + ded.cleaning + ded.missing + ded.damaged + ded.pet + ded.rent) * 100) / 100;

// --- legal deadline (fill-when-blank; the Deadline Watch flow may already have written it)
const deadlineDays = policy ? num(policy.fields['Deposit Return Deadline (Days)']) : 0;
const existingDeadline = iso(lf['Deposit Legal Deadline']);
const deadline = existingDeadline || (moveOut && deadlineDays ? addDays(moveOut, deadlineDays) : '');
if (!deadline) problems.push('cannot compute the legal deadline (no Deposit Return Deadline (Days) on the state row)');

// --- interest: pro-rated per calendar year, [accrualStart, accrualEnd) day count, rate per year from the table.
// Accrual END is the day the money actually goes back (owner's decision): Anticipated Return Date when set,
// else the statement date, and never before move-out. Matches her practice - her Chin letter accrued to the
// return date, not to move-out.
const interestRequired = !!(policy && policy.fields['Security Deposit Interest Required']);
let interest = 0; const yearsUsed = [];
const accrualStart = iso(lf['Interest Last Returned']) || leaseStart;
const anticipatedReturn = iso(lf['Anticipated Return Date']);
let accrualEnd = anticipatedReturn || todayIso;
if (moveOut && Date.parse(accrualEnd) < Date.parse(moveOut)) accrualEnd = moveOut;
if (interestRequired && accrualStart && accrualEnd) {
  if (Date.parse(accrualEnd) <= Date.parse(accrualStart)) {
    interest = 0;
  } else {
    const rateByYear = {};
    for (const r of rates) {
      const rf = r.fields || {}; const y = parseInt(rf['Year'], 10); let a = num(rf['Annual Rate']);
      if (a >= 0.1) a = a / 100;   // entered as percent points (0.52) instead of a fraction (0.0052)
      if (y) rateByYear[y] = a;
    }
    const y0 = parseInt(accrualStart.slice(0, 4), 10), y1 = parseInt(accrualEnd.slice(0, 4), 10);
    const missing = [];
    let total = 0;
    for (let y = y0; y <= y1; y++) {
      const ys = y === y0 ? accrualStart : y + '-01-01';
      const ye = y === y1 ? accrualEnd : (y + 1) + '-01-01';
      const days = Math.round((Date.parse(ye + 'T00:00:00Z') - Date.parse(ys + 'T00:00:00Z')) / 86400000);
      if (days <= 0) continue;
      if (rateByYear[y] === undefined) { missing.push(y); continue; }
      total += deposit * rateByYear[y] * days / 365;
      yearsUsed.push({ year: y, rate: rateByYear[y], days: days });
    }
    if (missing.length) problems.push('missing ' + (state || '') + ' interest rate for year(s) ' + missing.join(', ') + ' in Deposit Interest Rates');
    interest = Math.round(total * 100) / 100;
  }
}

// --- decision and balances
const net = Math.round((held + interest - deductions) * 100) / 100;
const returnAmt = Math.max(0, net);
const owes = Math.max(0, -net);
const decision = deductions > 0 ? 'Partial Return' : 'Full Return';
const outcome = owes > 0 ? 'owes' : (deductions > 0 ? 'partial' : 'full');

// --- people and address
const names = (Array.isArray(lf['Tenant Names (auto)']) ? lf['Tenant Names (auto)'] : []).map(s => String(s || '').trim()).filter(Boolean);
const pocName = String(first(lf['POC Full Name']) || '').trim() || names[0] || 'Tenant';
const tenantLine = names.length > 1 ? names.join(' & ') : (names[0] || pocName);
const nick = String(first(lf['POC Nickname']) || '').trim() || String(first(lf['POC First Name']) || '').trim() || pocName.split(' ')[0];
const street = String(pf['Street Address'] || '').split(NL).join(', ').replace(/\*+$/, '').trim();
const unitName = String(uf['Unit'] || '').trim();
const town = String(pf['Town'] || '').trim();
const zip = String(pf['Zip Code'] || '').trim();
const address = [street, unitName, [town, [state, zip].filter(Boolean).join(' ')].filter(Boolean).join(', ')].filter(Boolean).join(', ');
const tenantEmail = String(first(lf['POC Email']) || first(lf['Tenant Email (auto)']) || '').trim();

// --- comments block
let notes = String(lf['Deduction - Comments'] || '').trim();
if (interest > 0 && yearsUsed.length) {
  const stateFull = policy ? String(policy.fields['State Full Name'] || state) : state;
  const parts = yearsUsed.map(y => (y.rate * 100).toFixed(2).replace(/\.?0+$/, '') + '% for ' + y.year);
  notes = (notes ? notes + ' ' : '') + 'Interest was calculated daily from ' + dlong(accrualStart) + ' through ' + dlong(accrualEnd) +
    ' using the ' + stateFull + ' Banking Commissioner' + String.fromCharCode(39) + 's published rates, ' + parts.join(' and ') + '.';
}
if (!notes) notes = 'None';

const leaseEnd = iso(lf['Lease Expiration']) || moveOut;
const datePrefix = todayIso;
const docName = datePrefix + ' - Disposition of Security Deposit - ' + leaseName;

const ph = {
  '{{Tenant}}': tenantLine, '{{Tenant Nickname}}': nick, '{{Date}}': dlong(todayIso), '{{Address}}': address,
  '{{Lease Date}}': dlong(leaseStart), '{{Lease End Date}}': dlong(leaseEnd), '{{Move Out Date}}': dlong(moveOut),
  '{{InitialSecurity}}': money(deposit), '{{PetDeposit}}': money(petDep), '{{Interest}}': money(interest), '{{TotalDeposit}}': money(held + interest),
  '{{RepairCosts}}': money(ded.repair), '{{RepairNotes}}': String(lf['Deduction - R&M Notes'] || '').trim(),
  '{{CleaningCosts}}': money(ded.cleaning), '{{MissingFurniture}}': money(ded.missing), '{{DamagedFurniture}}': money(ded.damaged),
  '{{PetDamage}}': money(ded.pet), '{{UnpaidRent}}': money(ded.rent), '{{TotalDeductions}}': money(deductions),
  '{{BalancetoTenant}}': money(returnAmt), '{{BalancetoLandlord}}': money(owes), '{{Notes}}': notes
};
const docRequests = Object.keys(ph).map(k => ({ replaceAllText: { containsText: { text: k, matchCase: true }, replaceText: ph[k] } }));

const leaseCalcFields = {
  %%VAO::FLD::Leases::Interest on Deposit%%: interest           // Interest on Deposit (the full/partial decision stays internal - the Deposit Decision field was deliberately dropped)
};
if (!existingDeadline && deadline) leaseCalcFields.%%VAO::FLD::Leases::Deposit Legal Deadline%% = deadline;   // Deposit Legal Deadline (fill-when-blank)

const ok = problems.length === 0;
const alertText = ok ? '' :
  ':warning: *Security deposit disposition cannot proceed* - ' + leaseName + NL +
  problems.map(p => '- ' + p).join(NL) + NL +
  'Lease marked *Needs Attention*. Fix the data and set Security Deposit Disposition back to *Prepare*.' + NL +
  'https://airtable.com/' + '%%VAO::BASE_ID%%' + '/' + '%%VAO::TBL::Leases%%' + '/' + L.id;

return [{ json: {
  ok, error: problems.join('; '), alertText,
  leaseId: L.id, leaseName, state, moveOut, leaseStart, leaseEnd, accrualStart, accrualEnd, deadline, deadlineDays,
  deposit, petDep, held, interest, interestRequired, yearsUsed, deductions, ded, net, returnAmt, owes, decision, outcome,
  names, pocName, nick, tenantLine, address, unitName, tenantEmail,
  folderId, folderUrl, templateId, docName, pdfName: docName + '.pdf', placeholders: ph, docRequests, leaseCalcFields, notes
} }];

const c = $('Compute & Validate').first().json;
const pdf = $('Upload PDF').first().json || {};
const doc = $('Copy Template').first().json || {};
const NL = String.fromCharCode(10);
const money = (v) => '$' + Number(v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const days = Math.round((Date.parse(c.deadline + 'T00:00:00Z') - Date.parse(new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' }) + 'T00:00:00Z')) / 86400000);
const line = c.outcome === 'owes'
  ? ':red_circle: *Tenant owes: ' + money(c.owes) + '* (nothing returned)'
  : ':white_check_mark: *Return to tenant: ' + money(c.returnAmt) + '*';
const text =
  ':page_facing_up: *Security deposit disposition ready for approval* - ' + c.leaseName + NL +
  'Decision: *' + c.decision + '*' + NL +
  'Held ' + money(c.held) + ' (deposit ' + money(c.deposit) + ' + pet ' + money(c.petDep) + ')  |  Interest ' + money(c.interest) + '  |  Deductions ' + money(c.deductions) + NL +
  line + NL +
  'Legal deadline: ' + c.deadline + ' (' + (days >= 0 ? days + ' days left' : Math.abs(days) + ' days OVERDUE') + ')' + NL +
  'Statement: <' + (pdf.webViewLink || '') + '|PDF>  |  <https://docs.google.com/document/d/' + (doc.id || '') + '/edit|Google Doc>' + NL +
  'Tenant email will go to: ' + (c.tenantEmail || '_no email on the lease - it will come to you instead_');
return [{ json: { text: text } }];

// The approval step answers with a boolean, not text: one click, no typing.
// A 'Request changes' click routes to a second wait that collects the note.
// threadTs comes from the PROPOSAL post - $json.ts does not exist on a Slack post output
// (it is message_timestamp / message.ts), and an undefined thread_ts silently posts top-level.
const d = $json.data || {};
return [{ json: {
  approved: d.approved === true,
  respondedAt: d.respondedAt || '',
  threadTs: $('Post Proposal').first().json.message_timestamp
} }];

// Free text from the second wait, only reached when 'Request changes' was clicked.
const raw = String((($json.data || {}).text) || '').trim();
return [{ json: {
  changeNote: raw || '(no detail given)',
  threadTs: $('Parse Reply').first().json.threadTs
} }];

// Renders the tenant email from the child flow's Automations row (Email Subject / Email Template).
// Falls back to hardcoded copy if the cells are empty. Passes the PDF binary straight through.
const c = $('Compute & Validate').first().json;
const tpl = ((($('Fetch Email Template').first().json.records) || [])[0] || {}).fields || {};
const NL = String.fromCharCode(10);
const money = (v) => '$' + Number(v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const dlong = (s) => s ? new Date(s + 'T00:00:00Z').toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' }) : '';

let result = '';
if (c.outcome === 'full') {
  result = 'Good news: your full deposit is being returned. The amount coming back to you is ' + money(c.returnAmt) +
    (c.interest > 0 ? ', which includes ' + money(c.interest) + ' in interest' : '') + '.';
} else if (c.outcome === 'partial') {
  result = 'After the deductions itemized in the attached statement, ' + money(c.returnAmt) + ' is being returned to you' +
    (c.interest > 0 ? ' (this includes ' + money(c.interest) + ' in interest)' : '') + '. The statement lists each deduction and the reason for it.';
} else {
  result = 'The deductions itemized in the attached statement come to more than the deposit we held, so no deposit is being returned and a balance of ' +
    money(c.owes) + ' is due to %%VAO::VAR::BUSINESS_NAME%%. Please reply to this email so we can arrange payment.';
}
const T = {
  FirstName: c.nick, Address: c.address, Unit: c.unitName, MoveOutDate: dlong(c.moveOut),
  ReturnAmount: money(c.returnAmt), OwedAmount: money(c.owes), Interest: money(c.interest), Deductions: money(c.deductions), Held: money(c.held),
  Deadline: dlong(c.deadline), ResultBlock: result,
  ReturnLine: c.outcome === 'owes' ? '' : '%%VAO::VAR::DEPOSIT_RETURN_NOTE%%'
};
const DEF_S = 'Your security deposit disposition - {Address}';
const DEF_B = 'Hi {FirstName},' + NL + NL + 'Attached is the disposition statement for the security deposit on {Address}. It itemizes the deposit we held, any interest, and any deductions.' + NL + NL + '{ResultBlock}' + NL + NL + '{ReturnLine}' + NL + NL + 'If you have any questions about the statement, just reply to this email.' + NL + NL + 'Best wishes in your next chapter,';
let subject = String(tpl['Email Subject'] || '').trim() || DEF_S;
let body = String(tpl['Email Template'] || '').trim();
if (!body) { body = DEF_B; subject = subject + ' [default copy - template cell empty]'; }
const fill = (s) => String(s).replace(/\{(\w+)\}/g, (m, k) => (T[k] !== undefined ? T[k] : m));
subject = fill(subject); body = fill(body);
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let t = esc(body).replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
t = t.split(/\n\s*\n/).filter(p => p.trim()).map(p => {
  const lines = p.split(NL);
  if (lines.length && lines.every(l => l.trim().startsWith('- '))) return '<ul>' + lines.map(l => '<li>' + l.trim().slice(2) + '</li>').join('') + '</ul>';
  return '<p>' + lines.join('<br>') + '</p>';
}).join('');
const SIG = "<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"color:rgb(51,51,51);font-size:14px;line-height:1.5\"><tbody><tr><td style=\"padding-right:18px;border-right:3px solid rgb(245,158,11);vertical-align:middle\"><img width=\"96\" height=\"67\" alt=\"%%VAO::VAR::BUSINESS_NAME%%\" src=\"%%VAO::VAR::SIGNATURE_IMAGE_URL%%\"></td><td style=\"padding-left:18px;vertical-align:middle\"><div style=\"font-size:17px;font-weight:bold;color:rgb(31,41,55);margin-bottom:2px\">%%VAO::VAR::AGENT_NAME%% Hartwell</div><div style=\"font-size:13px;color:rgb(107,114,128);margin-bottom:10px\">Tenant Success&nbsp;&nbsp;|&nbsp;&nbsp;%%VAO::VAR::BUSINESS_NAME%%</div><div style=\"font-size:13px;color:rgb(55,65,81)\"><a href=\"mailto:%%VAO::VAR::AGENT_EMAIL%%\" style=\"color:rgb(55,65,81)\">%%VAO::VAR::AGENT_EMAIL%%</a></div><div style=\"font-size:13px;color:rgb(55,65,81)\"><a href=\"%%VAO::VAR::OWNER_WEBSITE_URL%%\" style=\"color:rgb(245,158,11);font-weight:600\">%%VAO::VAR::OWNER_WEBSITE%%</a></div></td></tr></tbody></table>";
const html = t + SIG;
const realTo = String(c.tenantEmail || '').trim();
const to = realTo || '%%VAO::VAR::OWNER_EMAIL%%';
if (!realTo) subject = '[NO TENANT EMAIL ON LEASE] ' + subject;
// Name the attachment. The Drive download returns the bytes with no filename, so n8n calls the
// binary 'data' and the tenant would receive "data.pdf" unless this is set explicitly.
const binary = $input.first().binary || {};
if (binary.data) {
  binary.data.fileName = c.pdfName;
  binary.data.fileExtension = 'pdf';
  binary.data.mimeType = 'application/pdf';
}
return [{ json: { to, subject, html, realTo, fileName: c.pdfName }, binary: binary }];

// The 'Return security deposit' task you complete once the money has moved.
// Its TITLE carries '(Full Return)' or '(Partial Return)': the Airtable automation
// 'Security deposit return task complete -> lease Full / Partial' branches on that text.
const c = $('Compute & Validate').first().json;
const em = $('Render Email').first().json;
const pdf = $('Upload PDF').first().json || {};
const NL = String.fromCharCode(10);
const money = (v) => '$' + Number(v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const us = (iso) => iso ? iso.slice(5, 7) + '-' + iso.slice(8, 10) + '-' + iso.slice(0, 4) : '';
const todayIso = new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
const addDays = (s, n) => new Date(Date.parse(s + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
const d = c.ded || {};
const yearLines = (c.yearsUsed || []).map(y => y.year + ': ' + y.days + ' days at ' + (y.rate * 100).toFixed(2) + '% = ' + money(c.deposit * y.rate * y.days / 365));
const title = 'Return security deposit - ' + c.pocName + ' - ' + money(c.returnAmt) + ' due back' + (c.owes > 0 ? ', tenant owes ' + money(c.owes) : '') + ' (' + c.decision + ')';
const lines = [
  'Tenant: ' + c.tenantLine + (em.realTo ? ' <' + em.realTo + '>' : ' (no email on lease)'),
  'Unit: ' + c.address,
  'Move-out: ' + us(c.moveOut) + '   Legal deadline: ' + us(c.deadline),
  '',
  'THE MATH',
  'Security deposit ' + money(c.deposit) + ' + pet deposit ' + money(c.petDep) + ' = held ' + money(c.held),
  'Interest ' + money(c.interest) + (yearLines.length ? ' (' + yearLines.join('; ') + ')' : (c.interestRequired ? '' : ' (not required in ' + c.state + ')')),
  'Deductions ' + money(c.deductions) + ' = R&M ' + money(d.repair) + ' + cleaning ' + money(d.cleaning) + ' + missing items ' + money(d.missing) + ' + damaged items ' + money(d.damaged) + ' + pet damage ' + money(d.pet) + ' + unpaid rent ' + money(d.rent),
  money(c.held) + ' + ' + money(c.interest) + ' - ' + money(c.deductions) + ' = ' + money(c.net),
  '',
  'DUE BACK TO TENANT: ' + money(c.returnAmt) + (c.owes > 0 ? '   (tenant owes landlord ' + money(c.owes) + ')' : ''),
  'Decision: ' + c.decision,
  '',
  'Statement PDF: ' + (pdf.webViewLink || ''),
  'Statement emailed to ' + em.to + ' on ' + us(todayIso) + '.',
  'When the money has gone out, mark this task 5. Complete - the lease flips to ' + (c.decision === 'Full Return' ? 'Full' : 'Partial') + ' automatically.',
  'Lease: https://airtable.com/%%VAO::BASE_ID%%/%%VAO::TBL::Leases%%/' + c.leaseId
];
const daysLeft = Math.round((Date.parse(c.deadline + 'T00:00:00Z') - Date.parse(todayIso + 'T00:00:00Z')) / 86400000);
const taskFields = {
  %%VAO::FLD::Tasks::Title%%: title,                                   // Title
  %%VAO::FLD::Tasks::Task Description%%: lines.join(NL),                          // Task Description
  %%VAO::FLD::Tasks::Status%%: '1. Not Started',                        // Status
  %%VAO::FLD::Tasks::Assigned Employee%%: ['%%VAO::VAR::ASSIGNED_EMPLOYEE_RECORD_ID%%'],                        // Assigned Employee
  %%VAO::FLD::Tasks::Priority Level%%: 100,                                     // Priority Level
  %%VAO::FLD::Tasks::Related Lease%%: [c.leaseId],                             // Related Lease
  %%VAO::FLD::Tasks::Due Date%%: addDays(todayIso, 2),                    // Due Date (our target)
  %%VAO::FLD::Tasks::Deadline%%: c.deadline,                              // Deadline (legal)
  %%VAO::FLD::Tasks::Immediate Need?%%: daysLeft <= 7                            // Immediate Need?
};
if (c.returnAmt > 0) taskFields.%%VAO::FLD::Tasks::Amount Owed%% = c.returnAmt;   // Amount Owed -> the money-owed chase in Deadline Watch
return [{ json: { title, taskFields, daysLeft } }];
